});

const RAW_MAP = {"backlog": "Backlog ", "valor_of": "Valor OF", "acum_2025": "Acum 2025", "enero": "Enero", "enero_upside": "Upside", "febrero": "Febrero", "febrero_upside": "Upside_1", "marzo": "Marzo", "marzo_upside": "Upside_2", "q1": "Q1", "abril": "Abril", "abril_upside": "Upside_3", "mayo": "Mayo", "mayo_upside": "Upside_4", "junio": "Junio", "junio_upside": "Upside_5", "q2": "Q2", "julio": "Julio", "julio_upside": "Upside_6", "agosto": "Agosto", "agosto_upside": "Upside_7", "septiembre": "Septiembre", "septiembre_upside": "Upside_8", "q3": "Q3", "octubre": "Octubre", "octubre_upside": "Upside_9", "noviembre": "Noviembre", "noviembre_upside": "Upside_10", "diciembre": "Diciembre", "diciembre_upside": "Upside_11", "q4": "Q4", "total_ejecutado_acumulado": "TOTAL EJECUTADO ACUMULADO"};

function toNumberOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}

const items = $input.all();
const anterior = {};
const nuevoRaw = {};

for (const item of items) {
  if (item.json._origen === 'anterior') {
    anterior[String(item.json.pa)] = item.json;
  } else if (item.json._origen === 'nuevo') {
    nuevoRaw[String(item.json["# PA"])] = item.json;
  }
}

const timestamp = new Date().toISOString();
const cambios = [];

for (const pa in nuevoRaw) {
  const filaVieja = anterior[pa];
  if (!filaVieja) continue; // proyecto nuevo, no hay valor anterior que comparar

  const filaNuevaRaw = nuevoRaw[pa];
  const nombreProyecto = filaNuevaRaw["Nombre del Proyecto"];

  for (const campo in RAW_MAP) {
    const rawHeader = RAW_MAP[campo];
    const valorNuevo = toNumberOrNull(filaNuevaRaw[rawHeader]);
    const valorViejo = toNumberOrNull(filaVieja[campo]);
    if (valorNuevo !== valorViejo) {
      cambios.push({
        json: {
          timestamp,
          pa,
          nombre_del_proyecto: nombreProyecto,
          campo,
          valor_anterior: valorViejo,
          valor_nuevo: valorNuevo,
        }
      });
    }
  }
}

return cambios;

function toNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

const data = $json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];

const totalValorOfInfo = info.reduce((s, r) => s + toNum(r['Valor OF']), 0);
const totalBacklog2026 = info.reduce((s, r) => s + toNum(r['Backlog 2026']), 0);
const infoConEstadoContrato = info.filter(r => r['Estado contrato']);
const contratosVigentes = infoConEstadoContrato.filter(r => r['Estado contrato'] === 'Contrato vigente').length;
const contratosVencidos = infoConEstadoContrato.filter(r => r['Estado contrato'] === 'Contrato vencido').length;
const pctContratosVigentes = infoConEstadoContrato.length
  ? Math.round((contratosVigentes / infoConEstadoContrato.length) * 1000) / 10
  : null;

const porZona = {};
for (const r of info) {
  const z = r['Zona'] || 'Sin zona';
  porZona[z] = (porZona[z] || 0) + 1;
}

const valorOfPorPais = {};
for (const r of info) {
  const p = r['Pais'];
  if (!p) continue;
  valorOfPorPais[p] = (valorOfPorPais[p] || 0) + toNum(r['Valor OF']);
}
const valorOfPorPaisTop10 = Object.entries(valorOfPorPais)
  .sort((a, b) => b[1] - a[1]).slice(0, 10)
  .map(([pais, valor_of]) => ({ pais, valor_of }));

const totalBacklog = backlog.reduce((s, r) => s + toNum(r['Backlog ']), 0);
const totalValorOfBacklog = backlog.reduce((s, r) => s + toNum(r['Valor OF']), 0);
const backlogConVencimiento = backlog.filter(r =>
  r['Días para vencimiento'] !== undefined && r['Días para vencimiento'] !== '#N/A' && r['Días para vencimiento'] !== null
);
const proyectosVencidos = backlogConVencimiento.filter(r => toNum(r['Días para vencimiento']) < 0).length;
const pctProyectosVencidos = backlogConVencimiento.length
  ? Math.round((proyectosVencidos / backlogConVencimiento.length) * 1000) / 10
  : null;

const porEstado = {};
for (const r of backlog) {
  const e = r['Estado'] || 'Sin estado';
  porEstado[e] = (porEstado[e] || 0) + 1;
}

const backlogPorPm = {};
for (const r of backlog) {
  const pm = r['PM/Líder'];
  if (!pm) continue;
  backlogPorPm[pm] = (backlogPorPm[pm] || 0) + toNum(r['Backlog ']);
}
const backlogPorPmTop10 = Object.entries(backlogPorPm)
  .sort((a, b) => b[1] - a[1]).slice(0, 10)
  .map(([pm_lider, backlog]) => ({ pm_lider, backlog }));

const MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const UPSIDE_POR_MES = { Enero: 'Upside', Febrero: 'Upside_1', Marzo: 'Upside_2', Abril: 'Upside_3', Mayo: 'Upside_4', Junio: 'Upside_5', Julio: 'Upside_6', Agosto: 'Upside_7', Septiembre: 'Upside_8', Octubre: 'Upside_9', Noviembre: 'Upside_10', Diciembre: 'Upside_11' };
const TRIMESTRES = { Q1: ['Enero','Febrero','Marzo'], Q2: ['Abril','Mayo','Junio'], Q3: ['Julio','Agosto','Septiembre'], Q4: ['Octubre','Noviembre','Diciembre'] };

const serieMensual = MESES.map(mes => ({
  mes,
  commit: backlog.reduce((s, r) => s + toNum(r[mes]), 0),
  upside: backlog.reduce((s, r) => s + toNum(r[UPSIDE_POR_MES[mes]]), 0),
}));
const mensualPorMes = Object.fromEntries(serieMensual.map(m => [m.mes, m]));

const serieTrimestral = Object.entries(TRIMESTRES).map(([q, meses]) => ({
  trimestre: q,
  commit: meses.reduce((s, m) => s + mensualPorMes[m].commit, 0),
  upside: meses.reduce((s, m) => s + mensualPorMes[m].upside, 0),
}));

return [{
  json: {
    snapshot_id: 'current',
    timestamp: new Date().toISOString(),
    total_valor_of_info_proyectos: totalValorOfInfo,
    total_backlog_2026_info_proyectos: totalBacklog2026,
    pct_contratos_vigentes: pctContratosVigentes,
    contratos_vencidos: contratosVencidos,
    total_backlog: totalBacklog,
    total_valor_of_backlog: totalValorOfBacklog,
    pct_proyectos_vencidos: pctProyectosVencidos,
    serie_mensual_json: JSON.stringify(serieMensual),
    serie_trimestral_json: JSON.stringify(serieTrimestral),
    backlog_por_pm_json: JSON.stringify(backlogPorPmTop10),
    distribucion_zona_json: JSON.stringify(porZona),
    distribucion_estado_json: JSON.stringify(porEstado),
    valor_of_por_pais_json: JSON.stringify(valorOfPorPaisTop10),
  }
}];

function normalizarNombre(nombre) {
  return String(nombre || '')
    .normalize('NFD').replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function calcularClave(row) {
  const pa = row['# PA'];
  if (pa !== null && pa !== undefined && String(pa).trim() !== '' && String(pa) !== '#N/A') {
    return 'pa:' + String(pa).trim();
  }
  return 'nombre:' + normalizarNombre(row['Nombre del Proyecto']);
}

function excelSerialToDate(serial) {
  return new Date(Date.UTC(1899, 11, 30) + serial * 86400000);
}

function parseFechaFin(v) {
  if (v instanceof Date) return v;
  if (typeof v === 'number') return excelSerialToDate(v);
  if (typeof v === 'string') {
    // 'Fecha fin' viene en formato MM/DD/YYYY (americano), confirmado con datos reales
    // (ej. '12/14/2026' solo es valido como mes/dia, nunca dia/mes).
    const m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) {
      const mes = +m[1], dia = +m[2], anio = +m[3];
      if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;
      const fecha = new Date(Date.UTC(anio, mes - 1, dia));
      if (fecha.getUTCMonth() !== mes - 1 || fecha.getUTCDate() !== dia) return null;
      return fecha;
    }
  }
  return null;
}

function calcularEstadoYDias(fechaFinRaw, hoyStr) {
  const fechaFin = parseFechaFin(fechaFinRaw);
  if (!fechaFin) return { dias: null, estado: null };
  const hoy = new Date(hoyStr + 'T00:00:00Z');
  const dias = Math.round((fechaFin - hoy) / 86400000);
  let estado;
  if (dias <= 0) estado = 'Contrato vencido';
  else if (dias <= 30) estado = 'Contrato vence en menos de 30dias';
  else if (dias < 60) estado = 'Contrato finaliza en menos de 60dias';
  else estado = 'Contrato vigente';
  return { dias, estado };
}

function esVacia(row) {
  const pa = row['# PA'];
  const nombre = row['Nombre del Proyecto'];
  const paVacio = pa === null || pa === undefined || String(pa).trim() === '' || String(pa) === '#N/A';
  const nombreTexto = nombre === null || nombre === undefined ? '' : String(nombre).trim().toLowerCase();
  const nombreVacio = nombreTexto === '' || nombreTexto === 'n/a' || nombreTexto === '#n/a' || nombreTexto === 'na';
  return paVacio && nombreVacio;
}

const data = $json;
const infoSinVacias = (data.InfoProyectos || []).filter(row => !esVacia(row));
const backlogSinVacias = (data.Backlog || []).filter(row => !esVacia(row));
const filasVaciasDescartadas = (data.InfoProyectos || []).length - infoSinVacias.length
  + (data.Backlog || []).length - backlogSinVacias.length;
const fechaReferencia = new Date().toISOString().slice(0, 10);

function formatearFechaISO(fecha) {
  if (!fecha) return null;
  return fecha.toISOString().slice(0, 10);
}

const infoEnriquecido = infoSinVacias.map(row => {
  const { dias, estado } = calcularEstadoYDias(row['Fecha fin'], fechaReferencia);
  const fechaFinParsed = parseFechaFin(row['Fecha fin']);
  return {
    ...row,
    _clave: calcularClave(row),
    _dias_para_vencimiento: dias,
    _estado_contrato: estado,
    _fecha_fin_iso: formatearFechaISO(fechaFinParsed),
  };
});

const backlogEnriquecido = backlogSinVacias.map(row => ({ ...row, _clave: calcularClave(row) }));

return [{ json: { InfoProyectos: infoEnriquecido, Backlog: backlogEnriquecido, fechaReferencia, filasVaciasDescartadas } }];

function esNumero(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return false;
  return !isNaN(Number(v));
}

const data = $json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
const errores = [];

if (info.length < 10) errores.push(`Muy pocos proyectos en Info Proyectos: ${info.length}`);
if (backlog.length < 10) errores.push(`Muy pocos proyectos en Backlog: ${backlog.length}`);

const clavesInfo = new Set(info.map(r => r._clave));
const sinCruce = backlog.filter(r => !clavesInfo.has(r._clave));
const cruzan = backlog.length - sinCruce.length;
const pctCruce = backlog.length ? cruzan / backlog.length : 0;
if (pctCruce < 0.95) {
  const ejemplos = sinCruce.slice(0, 15).map(r => `${r._clave} (${r['Nombre del Proyecto'] || 'sin nombre'})`).join('; ');
  errores.push(`Cruce entre hojas muy bajo: ${(pctCruce * 100).toFixed(1)}% (minimo 95%). Sin cruce (${sinCruce.length} de ${backlog.length}): ${ejemplos}`);
}

const conValorOf = info.filter(r => esNumero(r['Valor OF'])).length;
const pctValorOf = info.length ? conValorOf / info.length : 0;
if (pctValorOf < 0.5) errores.push(`Muy pocos Valor OF numericos: ${(pctValorOf * 100).toFixed(1)}% (minimo 50%)`);

return [{ json: { ...data, _validacion: { valido: errores.length === 0, errores } } }];

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

function ordenarClaves(obj) {
  if (Array.isArray(obj)) return obj.map(ordenarClaves);
  if (obj && typeof obj === 'object') {
    return Object.keys(obj).sort().reduce((acc, k) => {
      acc[k] = ordenarClaves(obj[k]);
      return acc;
    }, {});
  }
  return obj;
}

const data = $json;
const payload = { InfoProyectos: data.InfoProyectos, Backlog: data.Backlog };
const canonical = JSON.stringify(ordenarClaves(payload));
const hash = cyrb53(canonical);

return [{ json: { ...data, _hash: hash } }];

function sqlStr(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function sqlNum(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return 'NULL';
  const n = Number(v);
  if (isNaN(n)) return 'NULL';
  const LIMITE_MONTO = 100000000;
  if (Math.abs(n) > LIMITE_MONTO) return 'NULL';
  return String(n);
}
function sqlInt(v) {
  if (v === null || v === undefined) return 'NULL';
  return String(Math.round(v));
}
function sqlDate(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + v + "'::date";
}

const data = $('Calcular Hash').item.json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
const hash = data._hash;
const fechaReferencia = data.fechaReferencia;

const proyectosPorClave = new Map();
for (const row of info) proyectosPorClave.set(row._clave, row);
for (const row of backlog) if (!proyectosPorClave.has(row._clave)) proyectosPorClave.set(row._clave, row);

const backlogPorClave = new Map();
for (const row of backlog) if (!backlogPorClave.has(row._clave)) backlogPorClave.set(row._clave, row);
const backlogSinDuplicados = Array.from(backlogPorClave.values());

const proyectoValues = [];
for (const [clave, row] of proyectosPorClave) {
  proyectoValues.push(`(${sqlStr(clave)}, ${sqlStr(row['# PA'])}, ${sqlStr(row['Project ID'])}, ${sqlStr(row['# Opp.'])}, `
    + `${sqlStr(row['Nombre del Proyecto'])}, ${sqlStr(row['Cliente'])}, ${sqlStr(row['PM/Líder'])}, ${sqlStr(row['PM/Líder PSA'])}, `
    + `${sqlStr(row['Zona'])}, ${sqlStr(row['Pais'])}, ${sqlStr(row['Vendedor'])}, ${sqlStr(row['TSM'])}, `
    + `${sqlStr(row['Billing Type'])}, ${sqlStr(row['Billing Arrengement'])}, ${sqlStr(row['Estado'])}, `
    + `${sqlNum(row['Valor OF'])}, ${sqlNum(row['Valor OF Anterior'])}, ${sqlNum(row['ACUMULADO A HOY'])}, `
    + `${sqlNum(row['Consumido 2025'])}, ${sqlNum(row['Backlog 2026'])}, ${sqlDate(row._fecha_fin_iso)}, `
    + `${sqlInt(row._dias_para_vencimiento)}, ${sqlStr(row._estado_contrato)}, ${sqlStr(row['ESTATUS'])})`);
}

const sqlProyectosUpsert = `proyectos_upsert AS (
  INSERT INTO proyecto (
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, estado_contrato, estatus, primera_carga_id, ultima_carga_id
  )
  SELECT v.*, (SELECT id FROM nueva_carga), (SELECT id FROM nueva_carga)
  FROM (VALUES
${proyectoValues.join(',\n')}
  ) AS v(
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, estado_contrato, estatus
  )
  ON CONFLICT (clave) DO UPDATE SET
    num_pa = EXCLUDED.num_pa, project_id = EXCLUDED.project_id, num_opp = EXCLUDED.num_opp,
    nombre = EXCLUDED.nombre, cliente = EXCLUDED.cliente, pm_lider = EXCLUDED.pm_lider, pm_lider_psa = EXCLUDED.pm_lider_psa,
    zona = EXCLUDED.zona, pais = EXCLUDED.pais, vendedor = EXCLUDED.vendedor, tsm = EXCLUDED.tsm,
    billing_type = EXCLUDED.billing_type, billing_arrangement = EXCLUDED.billing_arrangement, estado = EXCLUDED.estado,
    valor_of = EXCLUDED.valor_of, valor_of_anterior = EXCLUDED.valor_of_anterior, acumulado_a_hoy = EXCLUDED.acumulado_a_hoy,
    consumido_2025 = EXCLUDED.consumido_2025, backlog_2026 = EXCLUDED.backlog_2026, fecha_fin = EXCLUDED.fecha_fin,
    dias_para_vencimiento = EXCLUDED.dias_para_vencimiento, estado_contrato = EXCLUDED.estado_contrato, estatus = EXCLUDED.estatus,
    ultima_carga_id = (SELECT id FROM nueva_carga), actualizado_en = now()
  RETURNING id, clave
)`;

const MESES = [
  ['Enero', 1, 'Upside'], ['Febrero', 2, 'Upside_1'], ['Marzo', 3, 'Upside_2'],
  ['Abril', 4, 'Upside_3'], ['Mayo', 5, 'Upside_4'], ['Junio', 6, 'Upside_5'],
  ['Julio', 7, 'Upside_6'], ['Agosto', 8, 'Upside_7'], ['Septiembre', 9, 'Upside_8'],
  ['Octubre', 10, 'Upside_9'], ['Noviembre', 11, 'Upside_10'], ['Diciembre', 12, 'Upside_11'],
];

const revenueMesValues = [];
for (const row of backlogSinDuplicados) {
  for (const [mesNombre, mesNum, upsideCol] of MESES) {
    const commit = sqlNum(row[mesNombre]);
    const upside = sqlNum(row[upsideCol]);
    revenueMesValues.push(`(${sqlStr(row._clave)}, ${mesNum}, ${commit === 'NULL' ? 0 : commit}, ${upside === 'NULL' ? 0 : upside})`);
  }
}

const sqlRevenueMes = `revenue_mes_insert AS (
  INSERT INTO revenue_mes (carga_id, proyecto_id, mes, commit_usd, upside_usd)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.mes, v.commit_usd, v.upside_usd
  FROM (VALUES
${revenueMesValues.join(',\n')}
  ) AS v(clave, mes, commit_usd, upside_usd)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING proyecto_id, mes, commit_usd, upside_usd
)`;

const revenueAnualValues = backlogSinDuplicados.map(row =>
  `(${sqlStr(row._clave)}, ${sqlNum(row['Acum 2025'])}, ${sqlNum(row['Backlog '])}, ${sqlNum(row['TOTAL EJECUTADO ACUMULADO'])})`
);

const sqlRevenueAnual = `revenue_anual_insert AS (
  INSERT INTO revenue_anual (carga_id, proyecto_id, acum_2025, backlog, total_ejecutado_acumulado)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.acum_2025, v.backlog, v.total_ejecutado
  FROM (VALUES
${revenueAnualValues.join(',\n')}
  ) AS v(clave, acum_2025, backlog, total_ejecutado)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING 1
)`;

const sqlMovimiento = `movimiento_insert AS (
  INSERT INTO movimiento (carga_id, carga_previa_id, proyecto_id, mes, tipo, monto, commit_anterior, commit_nuevo, upside_anterior, upside_nuevo)
  SELECT
    (SELECT id FROM nueva_carga), (SELECT id FROM carga_previa),
    n.proyecto_id, n.mes,
    CASE WHEN n.commit_usd > COALESCE(a.commit_usd, 0) THEN 'upside_a_commit' ELSE 'commit_a_upside' END,
    abs(n.commit_usd - COALESCE(a.commit_usd, 0)),
    a.commit_usd, n.commit_usd, a.upside_usd, n.upside_usd
  FROM revenue_mes_insert n
  LEFT JOIN revenue_mes a
    ON a.carga_id = (SELECT id FROM carga_previa) AND a.proyecto_id = n.proyecto_id AND a.mes = n.mes
  WHERE (SELECT id FROM carga_previa) IS NOT NULL
    AND abs(n.commit_usd - COALESCE(a.commit_usd, 0)) >= 1.0
  RETURNING 1
)`;

const sql = `BEGIN;
WITH
nueva_carga AS (
  INSERT INTO carga (archivo_nombre, datos_hash, fecha_referencia, filas_info, filas_backlog)
  VALUES ('CLOUD FORECAST GENERAL - NOLA FY26', ${sqlStr(hash)}, ${sqlStr(fechaReferencia)}, ${info.length}, ${backlog.length})
  RETURNING id
),
carga_previa AS (
  SELECT id FROM carga WHERE id < (SELECT id FROM nueva_carga) ORDER BY id DESC LIMIT 1
),
${sqlProyectosUpsert},
${sqlRevenueMes},
${sqlRevenueAnual},
${sqlMovimiento}
